function validate([points, k]) {
  if (!Array.isArray(points) || points.length < 2 || points.length > 100000) return 'points needs 2 to 10^5 entries.';
  for (const point of points) {
    if (!Array.isArray(point) || point.length !== 2) return 'Each point is a pair [x, y].';
    if (point.some(v => !Number.isInteger(v) || v < -1e8 || v > 1e8)) return 'Coordinates are whole numbers from -10^8 to 10^8.';
  }
  if (!Number.isInteger(k) || k < 0 || k > 2e8) return 'k is a whole number from 0 to 2 * 10^8.';
  let close = false;
  for (let i = 1; i < points.length; i++) {
    if (points[i][0] <= points[i - 1][0]) return 'The x-coordinates must strictly increase.';
    if (points[i][0] - points[i - 1][0] <= k) close = true;
  }
  if (!close) return 'At least one pair of points must have x-coordinates at most k apart.';
  return null;
}

