function findMaxValueOfEquation(points, k) {
  const deque = [];
  let head = 0;
  let best = -Infinity;

  for (const [x, y] of points) {
    while (head < deque.length && x - deque[head][0] > k) {
      head++;
    }
    if (head < deque.length) {
      best = Math.max(best, deque[head][1] + x + y);
    }
    const gain = y - x;
    while (head < deque.length && deque[deque.length - 1][1] <= gain) {
      deque.pop();
    }
    deque.push([x, gain]);
  }
  return best;
}

