function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? pick(1800, 2000) : pick(2, 8);
  const maxGap = large ? (rand() < 0.5 ? 100000 : 1000) : pick(1, 6);
  const span = large ? 100000000 : 12;
  let x = large ? -100000000 + pick(0, 1000) : pick(-10, 10);
  const points = [];
  for (let i = 0; i < n; i++) {
    points.push([x, pick(-span, span)]);
    x += pick(1, maxGap);
  }
  let smallest = Infinity;
  for (let i = 1; i < n; i++) smallest = Math.min(smallest, points[i][0] - points[i - 1][0]);
  // At least one pair must lie within k; when the random k misses every gap, use the smallest gap itself.
  let k = large ? (rand() < 0.2 ? 200000000 : pick(0, maxGap * pick(1, 20))) : pick(0, 10);
  if (k < smallest) k = smallest;
  return [points, k];
}
